// =====================================================================

// 1) OPT-OUT. Requisito de Meta: si piden la baja, se corta y no se
//    vuelve a escribir NUNCA. No puede depender de que el LLM lo detecte.
//    Ojo: "no me interesa" NO es opt-out, es un rechazo comercial comun.
const OPT_OUT = [
  // "baja" suelta NO alcanza: "estamos en baja temporada" es charla normal
  // y daria de baja a un lead sano para siempre. Se exige contexto.
  /\bdar(me|nos)? de baja\b|\bsolicito la baja\b|\bbaja de la (lista|base)\b/i,
  /\b(stop|unsubscribe|desuscribir|desuscribime)\b/i,
  /no me (escrib|contact|manden|mande|llamen|molest)/i,
  /dejen de (escrib|molest|contact|mandar)/i,
  // Enclitico pegado: "sacame", "borrenme", "saquenme" van en UNA palabra.
  // Ojo sacar -> saquen: cambia la raiz, por eso sa[cq] y no solo sac.
  /\b(borr|elimin|sa[cq]|quit)\w*me\b/i,
  /(borren|elimin\w*|saquen|quiten)\s+(me|mi|mis)\b/i,
  /no quiero (que me|recibir|mas mensaje)/i,
  /reportar como spam|es spam|esto es spam/i
];
const MSG_OPT_OUT = 'Entendido. Damos de baja el contacto y no volveremos a escribirle. Disculpe la molestia.';

