  // respuestaFija vacia = silencio deliberado (la baja ya se confirmo antes).
  // OJO: NO devolver [] aca. Con 0 items 'Responder al HTML' nunca corre y
  // la peticion queda colgada hasta el timeout. Se responde con texto vacio
  // y el cliente decide no pintar nada.
  return { json: { response: pre.respuestaFija || '', bloqueado: pre.bloqueado } };
}

// Respaldo para la demo: si el modelo falla (sin credito, 429, timeout),
// igual sale una respuesta coherente en vez de un error en pantalla.
let respuestaIA = '';

try {
  const item = $input.first().json || {};
  respuestaIA = (item.output || item.text || item.response || '').toString();
} catch (e) {
  respuestaIA = '';
}

const fallo = !respuestaIA.trim()
  || respuestaIA.includes('Error fetching')
  || respuestaIA.includes('429');

if (fallo) {
  // OJO: aca NO va $node[...] (sintaxis vieja del Function node).
  // En Code node es $('Nombre'). Con la sintaxis vieja esto tiraba error,
  // el catch se lo comia y el respaldo "inteligente" nunca corria.
  const ctx = pre;

  const lead = ctx.lead || {};
  const nombre = lead.primerNombre || 'Gabriela';
  const sistema = lead.sistema || 'SOFTLAND';
  const empresa = lead.empresa || 'su empresa';
  const paso = parseInt(ctx.paso) || 1;
  const txt = (ctx.input || '').toString().toLowerCase();

  // Match por PALABRA COMPLETA. Con includes('si') una respuesta como
  // "no necesito nada" contenia "si" dentro de "necesito" y el bot
  // contestaba "Excelente, le comparto el Calendly" a un rechazo.
  const tiene = (palabras) => {
    const re = new RegExp('(^|[^a-zá-úñ])(' + palabras.join('|') + ')([^a-zá-úñ]|$)', 'i');
    return re.test(txt);
  };

  const esTecnica = tiene(['api', 'apis', 'sql', 'script', 'agip', 'arba', 'sicore', 'webhook', 'endpoint']);
  const esPrecio = tiene(['precio', 'precios', 'cuanto', 'cuánto', 'sale', 'cuesta', 'costo', 'presupuesto', 'tarifa']);
  const acepta = tiene(['si', 'sí', 'dale', 'claro', 'perfecto', 'obvio', 'agendar', 'agendemos', 'coordinemos'])
    || /me sirve|me viene bien|de acuerdo/i.test(txt);
  const rechaza = /no me interesa|no gracias|no, gracias|dejen de|no contact|ya no trabajo/i.test(txt);
  const queEs = /qu[eé] (es|hac|se trata|hacen)|de qu[eé] se trata|no me acuerdo|recordame/i.test(txt);

  if (esTecnica || esPrecio) {
    respuestaIA = MSG_ESCALAR;
  } else if (rechaza) {
    respuestaIA = 'Entendido ' + nombre + ', le agradezco la respuesta. Quedamos a disposicion si en el futuro les resulta util retomarlo.';
  } else if (queEs) {
    respuestaIA = 'Claro ' + nombre + '. Automatizamos la carga de facturas al sistema contable con IA, para que administracion deje de cargarlas a mano. Como viene el tema en ' + empresa + '?';
  } else if (paso >= 3 && acepta) {
    respuestaIA = 'Excelente ' + nombre + '. Le comparto la opcion para agendar la reunion en Calendly segun la disponibilidad de su agenda:';
  } else if (paso >= 2) {
    // Recien en la segunda respuesta se propone la reunion.
    respuestaIA = 'Le propongo revisarlo en una llamada corta de 10 minutos, ' + nombre + '. Le muestro como quedaria funcionando sobre ' + sistema + '.';
  } else {
    // ETAPA 1: reconectar, sin pedir la reunion.
    respuestaIA = 'Hola ' + nombre + '. Los habiamos contactado por la carga contable en ' + sistema + '. Como viene ese tema hoy en ' + empresa + '?';
  }
}

// FUERA DE TEMA: preguntas ajenas al negocio (la receta de hamburguesa).
// Se desvia con cortesia y la conversacion SIGUE ABIERTA. Va ANTES del
// chequeo de ESCALAR: no se le hace perder el tiempo a un humano con algo
// que ningun humano del equipo iba a contestar.
// OJO con el texto de abajo: NO puede contener "especialista", "derivar",
// "escalar" ni "chatwoot". La red de seguridad que sigue lo convertiria en
// MSG_ESCALAR, y el front pinta la tarjeta de escalacion con esas palabras.
if (/\bfuera[_ ]?de[_ ]?tema\b/i.test(respuestaIA)) {
  const empresaFT = ((pre.lead || {}).empresa) || 'su empresa';
  respuestaIA = 'Me voy a limitar a los temas de gestion de facturas y gastos, que es donde puedo serle util. Como viene hoy esa parte en ' + empresaFT + '?';
}

// El modelo casi nunca devuelve ESCALAR literal: lo parafrasea
// ("Necesito escalar su consulta..."). Verificado en pruebas reales.
// Por eso se matchea la palabra completa sin distinguir mayusculas.
// Este token de control NUNCA puede llegar crudo al cliente.
if (/\bescalar\b|\bderiv(o|ar|amos)\b|\bespecialista\b/i.test(respuestaIA)) {
  respuestaIA = MSG_ESCALAR;
}

// Ultima red: si el modelo se puso a especular igual, se deriva.
if (/no tengo (informaci|datos)|no cuento con|como (IA|modelo)|puedo inferir|probablemente sea/i.test(respuestaIA)) {
  respuestaIA = MSG_ESCALAR;
}

// Se le avisa al front por que motivo cerro, para que no siga mandando.
// 'escalado' = lo tomo un humano. 'despedida' = la charla termino bien.
let cierre = '';
if (respuestaIA === MSG_ESCALAR) cierre = 'escalado';
else if (/ adi[oó]s |hasta pronto|quedamos a disposicion|quedamos a disposici[oó]n|le agradezco la respuesta|damos de baja/i.test(respuestaIA)) cierre = 'despedida';

return { json: { response: respuestaIA, cierre: cierre } };
